#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long sum = 0;
    if (n > 1) {
        sum = 1; // 1 is always a proper divisor for n>1
        for (long i = 2; i * i <= n; ++i) {
            if (n % i == 0) {
                sum += i;
                long other = n / i;
                if (other != i) {
                    sum += other;
                }
            }
        }
    }
    // n == 1 => sum stays 0 (no proper divisors)

    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }
    return 0;
}
}
